mapper.select:
SELECT D.BIZ_YR AS BIZ_YR /*서비스실행사업년도*/ , B.RSFR_INST_NO AS INST_NO /*기관번호*/ , (SELECT INST_NM FROM SAA000 WHERE INST_NO = B.RSFR_INST_NO) AS INST_NM /*기관명*/ , B.RESRCE_NO AS RESRCE_NO /*자원번호*/ , B.PVSN_RESRCE_NM AS RESRCE_NM /*자원명*/ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'BGT_IMPL_CL_SE_CD' AND CMMNS_CD_VALUE = A.BGT_IMPL_CL_SE_CD) AS BGT_IMPL_CL_SE_NM /*예산집행명*/ , A.BGT_IMPL_CL_SE_CD AS BGT_IMPL_CL_SE_CD /*예산집행분류구분코드*/ , E.BGT_IMPL_LCLAS_SE_CD AS BGT_IMPL_LCLAS_SE_CD /*예산집행대분류구분코드*/ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'BGT_IMPL_LCLAS_SE_CD' AND CMMNS_CD_VALUE = E.BGT_IMPL_LCLAS_SE_CD) AS BGT_IMPL_SE_NM_L /*예산집행대분류명*/ , E.BGT_IMPL_MLSFC_SE_CD AS BGT_IMPL_MLSFC_SE_CD /*예산집행중분류구분코드*/ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'BGT_IMPL_MLSFC_SE_CD' AND CMMNS_CD_VALUE = E.BGT_IMPL_MLSFC_SE_CD) AS BGT_IMPL_SE_NM_M /*예산집행중분류명*/ , E.BGT_IMPL_SCLAS_SE_CD AS BGT_IMPL_SCLAS_SE_CD /*예산집행소분류구분코드*/ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'BGT_IMPL_SCLAS_SE_CD' AND CMMNS_CD_VALUE = E.BGT_IMPL_SCLAS_SE_CD) AS BGT_IMPL_SE_NM_S /*예산집행소분류명*/ , A.APLY_PIC_NO /*신청자번호*/ , DEC_B64((SELECT FLNM_ENCPT FROM SCA100 WHERE ENFSN_NO = A.APLY_PIC_NO)) AS APLCNT_NM /*신청자명*/ , A.APLY_DT AS APLY_DT /*신청일자*/ , A.APRV_DT AS APRV_DT /*승인일자*/ , A.APRV_PIC_NO /*승인자번호*/ , DEC_B64((SELECT FLNM_ENCPT FROM SCA100 WHERE ENFSN_NO = A.APRV_PIC_NO)) AS APRV_PIC_NM /*승인자명*/ , (SELECT CMMNS_CD_VALUE_NM FROM SAC100 WHERE CMMNS_CD_ID = 'BGT_IMPL_CL_SE_CD' AND CMMNS_CD_VALUE = A.BGT_IMPL_CL_SE_CD) AS APRV_STTS_SE_NM /*승인상태명*/ , A.APRV_STTS_SE_CD AS APRV_STTS_SE_CD /*승인상태구분코드*/ , A.PRGRS_RESULT_CN AS PRGRS_RESULT_CN /*진행결과 내용*/ , E.BGT_IMPL_AMT AS BGT_IMPL_AMT /*예산집행금액*/
FROM AFA510 A /*예산실적 테이블*/ LEFT OUTER JOIN SDA100 B /*자원기본 테이블*/ ON A.RESRCE_NO = B.RESRCE_NO LEFT OUTER JOIN SDA420 C /*서비스실행사업 테이블*/ ON B.SRVC_EXCN_BIZ_NO = C.SRVC_EXCN_BIZ_NO LEFT OUTER JOIN SDA400 D /*서비스사업 테이블*/ ON C.SRVC_BIZ_NO = D.SRVC_BIZ_NO LEFT OUTER JOIN AFA520 E /*예산실적상세 테이블*/ ON A.RESRCE_NO = E.RESRCE_NO AND A.BGT_IMPL_CL_SE_CD = E.BGT_IMPL_CL_SE_CD WHERE 1=1 AND A.RESRCE_NO = #{RESRCE_NO} AND A.BGT_IMPL_CL_SE_CD = #{BGT_IMPL_CL_SE_CD}
AND A.APRV_STTS_SE_CD = '2'

mapper.insert:
	INSERT INTO AFA510(                                                /*예산실적 테이블*/
	    RESRCE_NO                                                  /*자원번호*/
	    , BGT_IMPL_CL_SE_CD                                        /*예산집행분류구분코드*/
	    , APRV_STTS_SE_CD                                          /*승인상태구분코드*/
	    , APLY_DT                                                  /*신청일시*/
	    , APLY_PIC_NO                                              /*신청담당자번호*/
	    , FRST_RGTR_ID                                             /*최초등록자아이디*/
	    , LAST_MDFR_ID                                             /*최종수정자아이디*/
	) VALUES (
	    #{RESRCE_NO}
	    , #{BGT_IMPL_CL_SE_CD}
	    , #{APRV_STTS_SE_CD}
	    , SYSDATE
	    , #{APLY_PIC_NO}
	    , #{USER_ID}
	    , #{USER_ID}
    )

    INSERT INTO AFA520(                                                /*예산실적상세 테이블*/
        RESRCE_NO                                                  /*자원번호*/
        , BGT_IMPL_CL_SE_CD                                        /*예산집행분류구분코드*/
        , BGT_IMPL_LCLAS_SE_CD                                     /*예산집행대분류구분코드*/
        , BGT_IMPL_MLSFC_SE_CD                                     /*예산집행중분류구분코드*/
        , BGT_IMPL_SCLAS_SE_CD                                     /*예산집행소분류구분코드*/
        , BGT_IMPL_AMT                                             /*예산집행금액*/
        , FRST_RGTR_ID                                             /*최초등록자아이디*/
        , LAST_MDFR_ID                                             /*최종수정자아이디*/
    ) VALUES 

    (
	    #{item.RESRCE_NO}
	    , #{item.BGT_IMPL_CL_SE_CD}
	    , #{item.BGT_IMPL_LCLAS_SE_CD}
	    , #{item.BGT_IMPL_MLSFC_SE_CD}
	    , #{item.BGT_IMPL_SCLAS_SE_CD}
	    , NVL(#{item.BGT_IMPL_AMT},0)
	    , #{item.USER_ID}
	    , #{item.USER_ID}
    )

INSERT INTO AFA521(                                                /*예산실적상세 테이블*/
    RESRCE_NO                                                  /*자원번호*/
    , BGT_IMPL_CL_SE_CD                                        /*예산집행분류구분코드*/
    , BGT_IMPL_LCLAS_SE_CD                                     /*예산집행대분류구분코드*/
    , BGT_IMPL_MLSFC_SE_CD                                     /*예산집행중분류구분코드*/
    , BGT_IMPL_SCLAS_SE_CD                                     /*예산집행소분류구분코드*/
    , MDFCN_DT                                                 /*수정일시*/
    , BGT_IMPL_AMT                                             /*예산집행금액*/
    , FRST_RGTR_ID                                             /*최초등록자아이디*/
    , LAST_MDFR_ID                                             /*최종수정자아이디*/
) VALUES 

(
    #{item.RESRCE_NO}
    , #{item.BGT_IMPL_CL_SE_CD}
    , #{item.BGT_IMPL_LCLAS_SE_CD}
    , #{item.BGT_IMPL_MLSFC_SE_CD}
    , #{item.BGT_IMPL_SCLAS_SE_CD}
    , SYSDATE
    , NVL(#{item.BGT_IMPL_AMT},0)
    , #{item.USER_ID}
    , #{item.USER_ID}
)

mapper.update:
    UPDATE AFA510 SET
	    RESRCE_NO = #{RESRCE_NO}
	    , BGT_IMPL_CL_SE_CD = #{BGT_IMPL_CL_SE_CD}
	    , APRV_STTS_SE_CD = #{APRV_STTS_SE_CD}

		    , APRV_PIC_NO = #{APRV_PIC_NO}
		    , PRGRS_RESULT_CN = #{PRGRS_RESULT_CN}
            , APRV_DT = SYSDATE

	    , LAST_MDFR_ID = #{USER_ID}
	    , LAST_MDFCN_DT = SYSDATE
    WHERE 1=1
        AND RESRCE_NO = #{RESRCE_NO__origin}
        AND BGT_IMPL_CL_SE_CD = #{BGT_IMPL_CL_SE_CD__origin}

UPDATE AFA520 SET  
    RESRCE_NO = #{RESRCE_NO}
    , BGT_IMPL_CL_SE_CD = #{BGT_IMPL_CL_SE_CD}
    , LAST_MDFR_ID = #{USER_ID}
    , LAST_MDFCN_DT = SYSDATE
WHERE 1=1
    AND RESRCE_NO = #{RESRCE_NO__origin}
    AND BGT_IMPL_CL_SE_CD = #{BGT_IMPL_CL_SE_CD__origin}

